BEGIN;
SELECT plan(17);
SELECT is(payroll.preview_dates('2027-01-25',24,1,'following','Africa/Cairo')->>'ends_on','2027-02-24','25 → 24 cycle');
SELECT is(payroll.preview_dates('2027-01-26',25,1,'following','Africa/Cairo')->>'ends_on','2027-02-25','26 → 25 cycle');
SELECT is(payroll.preview_dates('2027-02-01',NULL,31,'ending','Africa/Cairo')->>'ends_on','2027-02-28','explicit last day');
SELECT is(payroll.preview_dates('2028-02-01',NULL,31,'ending','Africa/Cairo')->>'ends_on','2028-02-29','leap last day');
SELECT is(payroll.preview_dates('2027-02-01',29,31,'ending','Africa/Cairo')->>'ends_on','2027-02-28','cutoff29 clamps');
SELECT is(payroll.preview_dates('2027-02-01',30,31,'ending','Africa/Cairo')->>'ends_on','2027-02-28','cutoff30 clamps');
SELECT is(payroll.preview_dates('2027-02-01',31,31,'ending','Africa/Cairo')->>'ends_on','2027-02-28','cutoff31 clamps');
SELECT is(payroll.preview_dates('2028-02-01',29,31,'ending','Africa/Cairo')->>'ends_on','2028-02-29','leap cutoff29');
SELECT is(payroll.preview_dates('2028-02-01',30,31,'ending','Africa/Cairo')->>'ends_on','2028-02-29','leap cutoff30');
SELECT is(payroll.preview_dates('2028-02-01',31,31,'ending','Africa/Cairo')->>'ends_on','2028-02-29','leap cutoff31');
SELECT is(payroll.preview_dates('2027-01-26',25,31,'following','Africa/Cairo')->>'payment_on','2027-03-31','payment following month');
SELECT is(payroll.preview_dates('2027-01-01',NULL,31,'following','Africa/Cairo')->>'payment_on','2027-02-28','payment short month clamps');
SELECT throws_ok($$SELECT payroll.preview_dates('2027-01-01',25,24,'ending','Africa/Cairo')$$,'22023','payroll_payment_before_end','payment before end refused');
SELECT is(payroll.preview_dates('2027-02-01',25,25,'ending','Africa/Cairo')->>'ends_on','2027-02-25','reviewed short transition after Jan31');
SELECT is(payroll.preview_dates('2027-12-26',25,1,'following','Africa/Cairo')->>'ends_on','2028-01-25','year boundary');
SELECT throws_ok($$SELECT payroll.preview_dates('2027-01-01',32,1,'following','Africa/Cairo')$$,'22023','payroll_invalid','unsupported day refused');
SELECT throws_ok($$SELECT payroll.preview_dates('2027-02-01',29,28,'ending','Africa/Cairo')$$,'22023','payroll_payment_before_end','February-only valid payment rule refused before it breaks a longer month');
SELECT * FROM finish();
ROLLBACK;
